def sedes_a_puntos(apps, schema_editor):
    """
    Lo que alcanzó a marcarse por SEDE o TERCERO (0086) pasa a PUNTOS del
    cliente con el mismo nombre, y las fotos ancladas a una sede o tercero
    quedan en el punto equivalente. Nada se pierde.
    """
    Punto = apps.get_model('gestion', 'PuntoRegistro')
    Programacion = apps.get_model('gestion', 'Programacion')
    Orden = apps.get_model('gestion', 'OrdenServicio')
    Foto = apps.get_model('gestion', 'FotoRegistro')

    def punto(cliente_id, nombre):
        existente = Punto.objects.filter(cliente_id=cliente_id, nombre__iexact=nombre).first()
        return existente or Punto.objects.create(cliente_id=cliente_id, nombre=nombre[:150])

    for Modelo in (Programacion, Orden):
        for obj in Modelo.objects.all():
            sitios = list(obj.sedes_registro.all()) + list(obj.terceros_registro.all())
            if sitios:
                obj.puntos_registro.add(*[punto(obj.cliente_id, s.nombre) for s in sitios])
    for foto in Foto.objects.exclude(sede__isnull=True, tercero__isnull=True).select_related('orden', 'sede', 'tercero'):
        sitio = foto.sede or foto.tercero
        foto.punto = punto(foto.orden.cliente_id, sitio.nombre)
        foto.save(update_fields=['punto'])


